import mujoco, numpy as np, time, itertools
REF="model_ref.xml"
FP=mujoco.mjtState.mjSTATE_FULLPHYSICS

def load(opt):
    m=mujoco.MjModel.from_xml_path(REF)
    for k,v in opt.items():
        setattr(m.opt,k,v)
    return m

def sim(m,seed,total=2.0):
    d=mujoco.MjData(m)
    rng=np.random.default_rng(seed)
    d.qpos+=rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    n=int(total/m.opt.timestep)
    for _ in range(n): mujoco.mj_step(m,d)
    st=np.zeros(mujoco.mj_stateSize(m,FP)); mujoco.mj_getState(m,d,st,FP)
    return st

mref=load({})
seeds=[0,1,2,3,4]
refs={s:sim(mref,s) for s in seeds}
def bench(m,seeds,reps=3):
    ts=[]
    for _ in range(reps):
        t0=time.perf_counter()
        for s in seeds: sim(m,s)
        ts.append((time.perf_counter()-t0)/len(seeds))
    return min(ts)

tref=bench(mref,seeds)
print("ref per-run %.4f"%tref)
cands=[]
for solver in [0,1,2]:
  for dt in [0.002,0.0025,0.003]:
    for jac in [1,2]:
      cands.append(dict(solver=solver,timestep=dt,jacobian=jac))
for opt in cands:
    m=load(opt)
    try:
        diffs=[np.abs(sim(m,s)-refs[s]).max() for s in seeds]
    except Exception as e:
        print(opt,"ERR",e); continue
    t=bench(m,seeds)
    print(f"{opt} maxdiff={max(diffs):.2e} ratio={t/tref:.3f}")
