    ts=[]
    for _ in range(reps):
        t0=time.perf_counter()
        for s in seeds: sim(m,s)
        ts.append((time.perf_counter()-t0)/len(seeds))
    return min(ts)
tref=bench(mref,seeds); print("ref %.4f"%tref)
res=[]
for integ in [0,3,2]:
  for solver in [0,2]:
    for dt in [0.002,0.0025,0.003,0.004]:
